prompt:
Passe alle Gutschein Design Elementen im style.css dem Hauptdesign an.

Hier ist das Design:

/* style.css /
.tablesorter-header-inner::after {
content: "\25b2 \25bc"; / hoch/runter-Pfeil aus dem Sonderzeichenvorrat */
font-size: 10px;
vertical-align: middle;
margin-left: 5px;
}

.tablesorter-header-inner:hover::after {
color: grey; /* Ändert die Farbe des Symbols bei Mouseover */
}

.gutschein {
margin: 20px;
}

.gutschein table {
width: 100%;
border-collapse: collapse;
}

.gutschein th {
text-align: center;
padding: 10px;
border: 1px solid black;
font-size: 1.2em;
}

.gutschein td {
text-align: center;
border: 1px solid black;
font-size: 0.9em;
}

.gutschein-btn {
background-color: rgb(5,100,115);
color: white;
font-size: 0.9em;
padding: 8px 16px;
border: none;
border-radius: 4px;
text-transform: uppercase;
font-weight: bold;
cursor: pointer;
transition: 0.3s;
}

.gutschein-btn:hover {
opacity: 0.8;
}

body {
font-family: Arial, sans-serif;
font-size: 13px;
line-height: 1.5;
background-color: #f2f2f2; /* Hellgrauer Hintergrund /
color: #333; / Dunkler Text */
}

tbody tr:nth-child(even) {
background-color: #f2f2f2; /* Helle Hintergrundfarbe für gerade Zeilen */
}

tbody tr:nth-child(odd) {
background-color: #fff; /* Weiße Hintergrundfarbe für ungerade Zeilen */
}

.wrapper {
display: grid;
grid-template-columns: 70% 30%;
grid-gap: 20px;
}

.additional-container {
background-color: #fff;
padding: 20px;
border-radius: 4px;
box-shadow: 0 2px 5px rgba(0, 0, 0, 0.15);
}

form {
background-color: #fff;
padding: 20px;
margin-right: 20px;
border-radius: 4px;
box-shadow: 0 2px 5px rgba(0, 0, 0, 0.15);
}
@media (max-width: 767px) {
.wrapper {
grid-template-columns: 1fr;
}
}
h1 {
font-size: 24px;
margin-bottom: 20px;
text-align: left;
color: #666; /* Mitteldunkler Titeltext */
}

.container {
max-width: 1200px;
margin: 0 auto;
padding-left: 20px;
padding-right: 20px;
padding-top: 20px;
padding-bottom: 20px;
background-color: #fff; /* Weißer Hintergrund im Hauptbereich /
border-radius: 4px;
box-shadow: 0 2px 5px rgba(0, 0, 0, 0.15); / Leichter Schatten */

}

a {
color: #0073aa; /* Blaue Links */
}

label {
display: block;
margin-bottom: 10px;
font-weight: bold;
color: #666; /* Mitteldunkler Text */
}

input[type="number"],
input.form-control,
.additional-container p {
width: 100%;
padding: 10px;
border-radius: 4px;
border: 1px solid #ccc;
box-sizing: border-box;
margin-bottom: 20px;
background-color: #f9f9f9; /* Helles Hintergrundfarbe für Eingabefelder /
color: #333; / Dunkle Textfarbe für Eingabefelder */
}

input[type="submit"] {
background-color: #f0ad4e; /* Pastellgelber Hintergrund */
color: #fff;
padding: 10px;
border: none;
border-radius: 4px;
cursor: pointer;
}

input[type="submit"]:hover {
background-color: #e29b34; /* Dunklerer Pastellgelber Hintergrund bei Mouseover */
}
